// Writes supabase/templates/*.html from the shared layout.
//
//   node supabase/scripts/build-email-templates.mjs supabase/templates
//   node supabase/scripts/build-email-templates.mjs supabase/templates --check
//
// The generated files are what gets pasted into the Supabase dashboard. They
// are committed so the templates are reviewable and diffable, but they are
// output — edit copy.mjs or layout.mjs and re-run, never edit them directly.
//
// --check re-renders and compares without writing, so a stale template fails
// `npm run typecheck` rather than being discovered in somebody's inbox.
//
// Modelled on apps/mobile/scripts/generate-icons.mjs, which solves the same
// problem for the launcher icons.

import { mkdirSync, readFileSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';

import { renderAuthEmail } from '../functions/_shared/email/render.mjs';

// The Go placeholders Supabase substitutes at send time. Getting these wrong
// is invisible until a real message goes out, so each one is spelled out
// rather than derived.
const JOBS = [
  {
    file: 'confirmation.html',
    kind: 'confirmation',
    // Kept as ConfirmationURL: /auth/confirmed is a static page with no token
    // handling, and it *is* claimed by the app, so the link opens LocaStar
    // itself on a phone.
    vars: { actionUrl: '{{ .ConfirmationURL }}' },
  },
  {
    file: 'recovery.html',
    kind: 'recovery',
    // Deliberately NOT ConfirmationURL. Microsoft Defender's Safe Links fetches
    // every URL in a message before the recipient sees it, and a Supabase
    // recovery link is single use — the scan spent it, so the first human click
    // reported otp_expired. Observed on a real hotmail.com address. With
    // token_hash the scanner gets a form and nothing is consumed until submit.
    // apps/web/src/pages/reset-password.astro already handles this shape.
    vars: { actionUrl: '{{ .RedirectTo }}?token_hash={{ .TokenHash }}&amp;type=recovery' },
  },
  {
    file: 'email_change.html',
    kind: 'email_change',
    // double_confirm_changes is on, so Supabase renders this file twice and
    // sends it to both the old and the new address with different tokens.
    vars: {
      actionUrl: '{{ .ConfirmationURL }}',
      email: '{{ .Email }}',
      newEmail: '{{ .NewEmail }}',
    },
  },
  { file: 'magic_link.html', kind: 'magic_link', vars: { actionUrl: '{{ .ConfirmationURL }}' } },
  { file: 'invite.html', kind: 'invite', vars: { actionUrl: '{{ .ConfirmationURL }}' } },
  // Token only — this template gets no ConfirmationURL and no RedirectTo.
  { file: 'reauthentication.html', kind: 'reauthentication', vars: { token: '{{ .Token }}' } },
  { file: 'password_changed.html', kind: 'password_changed', vars: {} },
];

const args = process.argv.slice(2);
const check = args.includes('--check');
const out = args.find((a) => !a.startsWith('--'));

if (!out) {
  console.error('usage: build-email-templates.mjs <output-dir> [--check]');
  process.exit(1);
}

if (!check) mkdirSync(out, { recursive: true });

let stale = 0;

for (const job of JOBS) {
  const { subject, html } = renderAuthEmail(job.kind, job.vars);
  const contents =
    '<!-- Generated by supabase/scripts/build-email-templates.mjs — do not edit. -->\n' +
    '<!-- Paste into Supabase → Authentication → Emails. Subject: ' + subject + ' -->\n' +
    html +
    '\n';

  const path = join(out, job.file);

  if (check) {
    const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
    if (current !== contents) {
      console.error('stale: ' + job.file + ' — run `npm run emails`');
      stale++;
    }
    continue;
  }

  writeFileSync(path, contents);
  console.log('wrote ' + job.file + ' (' + (Buffer.byteLength(contents) / 1024).toFixed(1) + 'kb)');
}

if (check) {
  if (stale) process.exit(1);
  console.log('email templates up to date');
}
